from fastapi import FastAPI, Body, Request
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.post("/default")
async def endpoint_default(request: Request, body: dict = Body(...)):
    return {"body": body}

@app.post("/strict")
async def endpoint_strict(request: Request, body: dict = Body(..., strict_content_type=True)):
    return {"body": body}

client = TestClient(app)

def test_default_no_header():
    # Default: no header should still parse as JSON
    response = client.post("/default", content='{"foo": "bar"}', headers={})
    assert response.status_code == 200
    assert response.json() == {"body": {"foo": "bar"}}

def test_strict_no_header():
    # Strict: no header should NOT parse as JSON. 
    # Since the endpoint expects a dict (Body(...)), it should fail validation if it's not parsed as JSON.
    response = client.post("/strict", content='{"foo": "bar"}', headers={})
    assert response.status_code == 422

def test_strict_with_header():
    # Strict: with header should parse as JSON
    response = client.post("/strict", content='{"foo": "bar"}', headers={"Content-Type": "application/json"})
    assert response.status_code == 200
    assert response.json() == {"body": {"foo": "bar"}}

def test_strict_wrong_header():
    # Strict: wrong header should NOT parse as JSON
    response = client.post("/strict", content='{"foo": "bar"}', headers={"Content-Type": "application/octet-stream"})
    assert response.status_code == 422

if __name__ == "__main__":
    import pytest
    pytest.main([__file__])
EOF
